// static
bool UnionTraits<::ash::enhanced_network_tts::mojom::TtsResponse::DataView, ::ash::enhanced_network_tts::mojom::TtsResponsePtr>::Read(
    ::ash::enhanced_network_tts::mojom::TtsResponse::DataView input,
    ::ash::enhanced_network_tts::mojom::TtsResponsePtr* output) {
  using UnionType = ::ash::enhanced_network_tts::mojom::TtsResponse;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kErrorCode: {
      ::ash::enhanced_network_tts::mojom::TtsRequestError result_error_code;
      if (!input.ReadErrorCode(&result_error_code))
        return false;

      *output = UnionType::NewErrorCode(result_error_code);
      break;
    }
    case Tag::kData: {
      ::ash::enhanced_network_tts::mojom::TtsDataPtr result_data;
      if (!input.ReadData(&result_data))
        return false;

      *output = UnionType::NewData(
          std::move(result_data));
      break;
    }
    default:

      return false;
  }
  return true;
}

