void EnhancedNetworkTtsAsyncWaiter::GetAudioData(
    TtsRequestPtr request, ::mojo::PendingReceiver<AudioDataObserver>* out_observer) {
  base::RunLoop loop;
  proxy_->GetAudioData(std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::mojo::PendingReceiver<AudioDataObserver>* out_observer
,
             ::mojo::PendingReceiver<AudioDataObserver> observer) {*out_observer = std::move(observer);
            loop->Quit();
          },
          &loop,
          out_observer));
  loop.Run();
}

::mojo::PendingReceiver<AudioDataObserver> EnhancedNetworkTtsAsyncWaiter::GetAudioData(
    TtsRequestPtr request) {
  ::mojo::PendingReceiver<AudioDataObserver> async_wait_result;
  GetAudioData(std::move(request),&async_wait_result);
  return async_wait_result;
}




